import{_ as o,a0 as r,w as p,s as d,I as e,x as i,a1 as a,A as n,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"如何使用 DockerHub | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 DockerHub | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 DockerHub | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 DockerHub | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180129 How to Use DockerHub","title":"如何使用 DockerHub","tag":"201804","desc":""},"relativePath":"201804/20180129 How to Use DockerHub.md","filePath":"[post].md"}'),u={name:"201804/20180129 How to Use DockerHub.md"};function k(g,s,b,h,c,f){const t=r("Link");return p(),d("div",null,[s[30]||(s[30]=e("h1",{id:"如何使用-dockerhub",tabindex:"-1"},[i("如何使用 DockerHub "),e("a",{class:"header-anchor",href:"#如何使用-dockerhub","aria-label":"Permalink to “如何使用 DockerHub”"},"​")],-1)),s[31]||(s[31]=e("blockquote",null,[e("p",null,"在這個 Docker 系列的最後一篇文章中，我們將講述在 DockerHub 上使用和發佈鏡像。")],-1)),s[32]||(s[32]=e("p",null,[e("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/dockerhub-container.jpg?itok=tvraxGzh",alt:""})],-1)),e("p",null,[s[3]||(s[3]=i("在前面的文章中，我們瞭解到了基本的 ",-1)),a(t,{href:"https://www.linux.com/blog/intro-to-linux/2017/12/container-basics-terms-you-need-know"},{default:n(()=>[...s[0]||(s[0]=[i("Docker 術語",-1)])]),_:1}),s[4]||(s[4]=i("，在 Linux 桌面、MacOS 和 Windows上 ",-1)),a(t,{href:"https://www.linux.com/blog/learn/intro-to-linux/how-install-docker-ce-your-desktop"},{default:n(()=>[...s[1]||(s[1]=[i("如何安裝 Docker",-1)])]),_:1}),s[5]||(s[5]=i("，",-1)),a(t,{href:"https://linux.cn/article-9541-1.html"},{default:n(()=>[...s[2]||(s[2]=[i("如何創建容器鏡像",-1)])]),_:1}),s[6]||(s[6]=i(" 並且在系統上運行它們。在本系列的最後一篇文章中，我們將討論如何使用 DockerHub 中的鏡像以及將自己的鏡像發佈到 DockerHub。",-1))]),s[33]||(s[33]=l(`<p>首先：什麼是 DockerHub 以及為什麼它很重要？DockerHub 是一個由 Docker 公司運行和管理的基於雲的存儲庫。它是一個在線存儲庫，Docker 鏡像可以由其他用户發佈和使用。有兩種庫：公共存儲庫和私有存儲庫。如果你是一家公司，你可以在你自己的組織內擁有一個私有存儲庫，而公共鏡像可以被任何人使用。</p><p>你也可以使用公開發布的官方 Docker 鏡像。我使用了很多這樣的鏡像，包括我的試驗 WordPress 環境、KDE plasma 應用程序等等。雖然我們上次學習瞭如何創建自己的 Docker 鏡像，但你不必這樣做。DockerHub 上發佈了數千鏡像供你使用。DockerHub 作為默認存儲庫硬編碼到 Docker 中，所以當你對任何鏡像運行 <code>docker pull</code> 命令時，它將從 DockerHub 下載。</p><h3 id="從-docker-hub-下載鏡像並在本地運行" tabindex="-1">從 Docker Hub 下載鏡像並在本地運行 <a class="header-anchor" href="#從-docker-hub-下載鏡像並在本地運行" aria-label="Permalink to “從 Docker Hub 下載鏡像並在本地運行”">​</a></h3><p>開始請查看本系列的前幾篇文章，以便繼續。然後，一旦 Docker 在你的系統上運行，你就可以打開終端並運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker images</span></span></code></pre></div><p>該命令將顯示當前系統上所有的 docker 鏡像。假設你想在本地機器上部署 Ubuntu，你可能會：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker pull ubuntu</span></span></code></pre></div><p>如果你的系統上已經存在 Ubuntu 鏡像，那麼該命令會自動將該系統更新到最新版本。因此，如果你想要更新現有的鏡像，只需運行 <code>docker pull</code> 命令，易如反掌。這就像 <code>apt-get update</code> 一樣，沒有任何的混亂和麻煩。</p><p>你已經知道了如何運行鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run -it &lt;image name&gt;</span></span>
<span class="line"><span>$ docker run -it ubuntu</span></span></code></pre></div><p>命令提示符應該變為如下內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>root@1b3ec4621737:/#</span></span></code></pre></div><p>現在你可以運行任何屬於 Ubuntu 的命令和實用程序，這些都被包含在內而且安全。你可以在 Ubuntu 上運行你想要的所有實驗和測試。一旦你完成了測試，你就可以銷燬鏡像並下載一個新的。在虛擬機中不存在系統開銷。</p><p>你可以通過運行 exit 命令退出該容器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ exit</span></span></code></pre></div><p>現在假設你想在系統上安裝 Nginx，運行 <code>search</code> 命令來找到需要的鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker search nginx</span></span></code></pre></div><p><img src="https://lh3.googleusercontent.com/aizMFFysICAEsgDDYrsrlqwoCgGbWVHtcOzgV9mAtV8IdBZgHPJTdHIZhWBNCRvOyJb108ZBajJ_Nz10yCxGSvk-AF-yvFxpojLdVu3Jjihcwaup6CQLc67A5nglBuGDaOZWcrbV" alt=""></p><p>正如你所看到的，DockerHub 上有很多 Nginx 鏡像。為什麼？因為任何人都可以發佈鏡像，各種鏡像針對不同的項目進行了優化，因此你可以選擇合適的鏡像。你只需要為你的需求安裝合適的鏡像。</p><p>假設你想要拉取 Bitnami 的 Nginx 鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker pull bitnami/nginx</span></span></code></pre></div><p>現在運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run -it bitnami/nginx</span></span></code></pre></div><h3 id="如何發佈鏡像到-docker-hub" tabindex="-1">如何發佈鏡像到 Docker Hub？ <a class="header-anchor" href="#如何發佈鏡像到-docker-hub" aria-label="Permalink to “如何發佈鏡像到 Docker Hub？”">​</a></h3>`,24)),e("p",null,[s[9]||(s[9]=i("在此之前，",-1)),a(t,{href:"https://linux.cn/article-9541-1.html"},{default:n(()=>[...s[7]||(s[7]=[i("我們學習瞭如何創建 Docker 鏡像",-1)])]),_:1}),s[10]||(s[10]=i("，我們可以輕鬆地將該鏡像發佈到 DockerHub 中。首先，你需要登錄 DockerHub，如果沒有賬户，請 ",-1)),a(t,{href:"https://hub.docker.com/"},{default:n(()=>[...s[8]||(s[8]=[i("創建賬户",-1)])]),_:1}),s[11]||(s[11]=i("。然後，你可以打開終端應用，登錄：",-1))]),s[34]||(s[34]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker login --username=&lt;USERNAME&gt;</span></span></code></pre></div><p>將 “&lt;USERNAME&gt;” 替換為你自己的 Docker Hub 用户名。我這裏是 arnieswap：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker login --username=arnieswap</span></span></code></pre></div><p>輸入密碼，你就登錄了。現在運行 <code>docker images</code> 命令來獲取你上次創建的鏡像的 ID。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker images</span></span></code></pre></div><p><img src="https://lh6.googleusercontent.com/tW1jDOugkX7J2FfyFyToM6B8m5OYFwMba-Ag5aezVGf2A5gsKJ47QrCh_TOKWgIKfE824Uc2Cwwwj9jWps1yJlUZqDyIceVQs-nEbKavFDxuUxLyd4thBA4_rsXrQH4r7hrG8FnD" alt=""></p>',6)),e("p",null,[s[13]||(s[13]=i("現在，假設你希望將鏡像 ",-1)),s[14]||(s[14]=e("code",null,"ng",-1)),s[15]||(s[15]=i(" 推送到 DockerHub，首先，我們需要標記該鏡像（",-1)),a(t,{href:"https://www.linux.com/blog/intro-to-linux/2017/12/container-basics-terms-you-need-know"},{default:n(()=>[...s[12]||(s[12]=[i("瞭解更多關於標記的信息",-1)])]),_:1}),s[16]||(s[16]=i("）：",-1))]),s[35]||(s[35]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker tag e7083fd898c7 arnieswap/my_repo:testing</span></span></code></pre></div><p>現在推送鏡像：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker push arnieswap/my_repo</span></span></code></pre></div><p>推送指向的是 [docker.io/arnieswap/my_repo] 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>12628b20827e: Pushed</span></span>
<span class="line"><span>8600ee70176b: Mounted from library/ubuntu</span></span>
<span class="line"><span>2bbb3cec611d: Mounted from library/ubuntu</span></span>
<span class="line"><span>d2bb1fc88136: Mounted from library/ubuntu</span></span>
<span class="line"><span>a6a01ad8b53f: Mounted from library/ubuntu</span></span>
<span class="line"><span>833649a3e04c: Mounted from library/ubuntu</span></span>
<span class="line"><span>testing: digest: sha256:286cb866f34a2aa85c9fd810ac2cedd87699c02731db1b8ca1cfad16ef17c146 size: 1569</span></span></code></pre></div><p>哦耶！你的鏡像正在上傳。一旦完成，打開 DockerHub，登錄到你的賬户，你就能看到你的第一個 Docker 鏡像。現在任何人都可以部署你的鏡像。這是開發軟件和發佈軟件最簡單，最快速的方式。無論你何時更新鏡像，用户都可以簡單地運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ docker run arnieswap/my_repo</span></span></code></pre></div><p>現在你知道為什麼人們喜歡 Docker 容器了。它解決了傳統工作負載所面臨的許多問題，並允許你在任何時候開發、測試和部署應用程序。通過遵循本系列中的步驟，你自己可以嘗試以下。</p><hr>`,9)),e("p",null,[s[18]||(s[18]=i("via: ",-1)),a(t,{href:"https://www.linux.com/blog/learn/intro-to-linux/2018/1/how-use-dockerhub"},{default:n(()=>[...s[17]||(s[17]=[i("https://www.linux.com/blog/learn/intro-to-linux/2018/1/how-use-dockerhub",-1)])]),_:1})]),e("p",null,[s[22]||(s[22]=i("作者：",-1)),a(t,{href:"https://www.linux.com/users/arnieswap"},{default:n(()=>[...s[19]||(s[19]=[i("Swapnil Bhartiya",-1)])]),_:1}),s[23]||(s[23]=i(" 譯者：",-1)),a(t,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[20]||(s[20]=[i("MjSeven",-1)])]),_:1}),s[24]||(s[24]=i(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:n(()=>[...s[21]||(s[21]=[i("wxy",-1)])]),_:1})]),e("p",null,[s[27]||(s[27]=i("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[25]||(s[25]=[i("LCTT",-1)])]),_:1}),s[28]||(s[28]=i(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:n(()=>[...s[26]||(s[26]=[i("Linux中國",-1)])]),_:1}),s[29]||(s[29]=i(" 榮譽推出",-1))])])}const D=o(u,[["render",k]]);export{x as __pageData,D as default};
